function creerFilePriorite() {
  const heap = [];

  function enqueue(val, priorite) {
    heap.push({ val, priorite });
    let i = heap.length - 1;
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2);
      if (heap[i].priorite < heap[parent].priorite) {
        [heap[i], heap[parent]] = [heap[parent], heap[i]];
        i = parent;
      } else {
        break;
      }
    }
  }

  function dequeue() {
    if (heap.length === 0) return undefined;
    const min = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      while (true) {
        let smallest = i;
        const left = 2 * i + 1;
        const right = 2 * i + 2;
        if (left < heap.length && heap[left].priorite < heap[smallest].priorite) {
          smallest = left;
        }
        if (right < heap.length && heap[right].priorite < heap[smallest].priorite) {
          smallest = right;
        }
        if (smallest !== i) {
          [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
          i = smallest;
        } else {
          break;
        }
      }
    }
    return min.val;
  }

  function taille() {
    return heap.length;
  }

  return { enqueue, dequeue, taille };
}
