```javascript
function creerSubject() {
  const subscribers = [];
  let isCompleted = false;

  return {
    next(val) {
      if (isCompleted) return;
      subscribers.forEach(sub => {
        if (sub.next) sub.next(val);
      });
    },
    error(err) {
      if (isCompleted) return;
      isCompleted = true;
      subscribers.forEach(sub => {
        if (sub.error) sub.error(err);
      });
    },
    complete() {
      if (isCompleted) return;
      isCompleted = true;
      subscribers.forEach(sub => {
        if (sub.complete) sub.complete();
      });
    },
    subscribe(observer) {
      subscribers.push(observer);
      return {
        unsubscribe: () => {
          const index = subscribers.indexOf(observer);
          if (index > -1) subscribers.splice(index, 1);
        }
      };
    }
  };
}
```

