function creerCircuitBreaker(fn, seuil, delaiResetMs) {
  let state = 'CLOSED';
  let failures = 0;
  let nextRetryTime = 0;

  return async function(...args) {
    if (state === 'OPEN') {
      if (Date.now() < nextRetryTime) {
        throw new Error('Circuit breaker is OPEN');
      }
      state = 'HALF_OPEN';
    }

    try {
      const result = await fn(...args);
      failures = 0;
      state = 'CLOSED';
      return result;
    } catch (err) {
      failures++;
      if (state === 'HALF_OPEN' || failures >= seuil) {
        state = 'OPEN';
        nextRetryTime = Date.now() + delaiResetMs;
      }
      throw err;
    }
  };
}
