function fusionnerIntervalles(tab) {
    if (tab.length === 0) return [];

    tab.sort((a, b) => a[0] - b[0]);

    const merged = [tab[0]];
    for (let i = 1; i < tab.length; i++) {
        const current = tab[i];
        const last = merged[merged.length - 1];

        if (current[0] <= last[1]) {
            last[1] = Math.max(last[1], current[1]);
        } else {
            merged.push(current);
        }
    }

    return merged;
}

function prefixeCommun(tab) {
    if (tab.length === 0) return "";

    let prefix = tab[0];
    for (let i = 1; i < tab.length; i++) {
        while (tab[i].indexOf(prefix) !== 0) {
            prefix = prefix.substring(0, prefix.length - 1);
            if (prefix === "") return "";
        }
    }
    return prefix;
}

function nombreDeBits1(n) {
    let count = 0;
    while (n > 0) {
        n = n & (n - 1);
        count++;
    }
    return count;
}

function medianeDeuxTries(a, b) {
    if (a.length > b.length) {
        return medianeDeuxTries(b, a);
    }

    const m = a.length;
    const n = b.length;
    let low = 0;
    let high = m;

    while (low <= high) {
        const partitionA = Math.floor((low + high) / 2);
        const partitionB = Math.floor((m + n + 1) / 2) - partitionA;

        const maxLeftA = partitionA === 0 ? -Infinity : a[partitionA - 1];
        const minRightA = partitionA === m ? Infinity : a[partitionA];

        const maxLeftB = partitionB === 0 ? -Infinity : b[partitionB - 1];
        const minRightB = partitionB === n ? Infinity : b[partitionB];

        if (maxLeftA <= minRightB && maxLeftB <= minRightA) {
            if ((m + n) % 2 === 0) {
                return (Math.max(maxLeftA, maxLeftB) + Math.min(minRightA, minRightB)) / 2;
            } else {
                return Math.max(maxLeftA, maxLeftB);
            }
        } else if (maxLeftA > minRightB) {
            high = partitionA - 1;
        } else {
            low = partitionA + 1;
        }
    }

    return 0;
}

function plusLongueSousSuiteCroissante(tab) {
    if (tab.length === 0) return 0;

    const tails = [];
    for (let num of tab) {
        let left = 0;
        let right = tails.length;

        while (left < right) {
            const mid = Math.floor((left + right) / 2);
            if (tails[mid] < num) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        if (left === tails.length) {
            tails.push(num);
        } else {
            tails[left] = num;
        }
    }

    return tails.length;
}
